using Maestro.Quest.Creation;
using Maestro.Quest.Diagnostics;
using Newtonsoft.Json.Linq;
namespace Maestro.Quest.Programs
{
    public static class FlowWorkFacts
    {
        static bool Available(BehaviourCatalog.FactContext context)=>context.Editor&&context.Editor.GetComponentInParent<RuntimeDiagnostics>();
        static readonly string[] Features={RuntimeDiagnosticFacts.Feature};
        public static BehaviourCatalog.FactDefinition Budget()=>new("runtime.flowWorkBudget",ProgramDataType.Read(JObject.Parse(@"{""record"":{""reservations"":""number"",""units"":""number"",""reservationLimit"":""number"",""unitLimit"":""number"",""streamSegments"":""number"",""queryHits"":""number"",""scoopSamples"":""number"",""rainSamples"":""number""}}")),
            "Liquid transfer work budget","Process-wide bounded requests for complete room pouring/scooping/rain passes. Reservations count registered requests, including queued rooms; units count granted opportunities. All registered vessels, including empty receivers and missing native views, contribute to demand. Admission precedes quantity changes; free moving vessels and their connected groups also require it before gravity. Hands and authored animations retain ownership. Complete dependent physics/liquid groups take fair turns on the shared early fixed-step clock, retained through a rendered frame. All registered moving vessel groups of a host share its complete pass and are admitted with both allowances together. A scheduled delay preserves input residency, accepted motion and the live episode, hides streams, invalidates rain exposure and never accrues skipped time. An unregistered refusal closes prior accepted flow. Current per-room spatial groups still share a whole-host opportunity because the bounded pass scans all vessels. Logical units cover pairwise cavities, bounded stream candidates/hits, exposure and participant-proof allowances; they are not measured CPU time, frame rate, memory or a PhysX budget. Geometry/proof internals, forces, contacts, external observations and engine costs are excluded. Reads may retire ineligible requests but never advance selection, admit work, load geometry, start physics or publish a flow episode.",null,null,
            (context,args)=>Available(context)?ProgramValue.Literal(FlowWorkResources.ObserveBudget()):null,features:Features);
        public static BehaviourCatalog.FactDefinition Schedule()=>new("runtime.flowWorkSchedule",ProgramDataType.Read(JObject.Parse(@"{""record"":{""step"":""number"",""executions"":""number"",""executionLimit"":""number"",""queued"":""number"",""queueLimit"":""number"",""units"":""number"",""unitLimit"":""number""}}")),
            "Liquid simulation opportunities","Read the current early fixed-step opportunity, granted whole-host passes and queued requests. The queue is bounded separately from simultaneous executions. The clock advances at approximately 20Hz with at least one rendered frame per opportunity; pauses do not accumulate fluid/rain debt. Priority is oldest unserved coupled group, then stable registration order. A finite unchanged group fitting both physics and liquid work limits receives a turn under continuing demand; oversize or queue-full requests are refused. Booked allowances may be stale until refreshed; a current reservation requires the whole group to match. This is scheduling evidence, not measured device performance. Reading cannot advance the clock or claim work.",null,null,
            (context,args)=>Available(context)?ProgramValue.Literal(FlowWorkResources.ObserveSchedule()):null,features:Features);
        public static BehaviourCatalog.FactDefinition Reservation()=>new("runtime.flowWorkReservation",ProgramDataType.Read(JObject.Parse(@"{""record"":{""reservationId"":""text"",""worldId"":""text"",""regionId"":""text"",""vessels"":""number"",""units"":""number"",""current"":""boolean""}}")),
            "Liquid transfer work request","Read one runtime.flowWorkBudget request by index, including pending requests. Indices may shift; reservationId is runtime-only. World/region identify the copied room owner. Current means this opportunity is granted and complete potential demand and owner still match, not that native geometry, a transfer or simulation is ready. Resizing credits the old grant and cannot evict peers or admit a room prefix. Earlier unserved requests receive priority at the next opportunity; call order and repeated reads do not advance it. Paused, inactive or destroyed hosts release requests; explicit internal ticks can step a disabled automatic loop for desktop verification. Reads are detached and cannot resume transfers or physics.",
            CapabilitySchema.Object(new JObject{["index"]=CapabilitySchema.Number(0,FlowWorkResources.MaximumReservations-1,true)}),new JObject{["index"]=0},
            (context,args)=>!Available(context)?null:FlowWorkResources.Observe((int)args["index"]) is JObject value?ProgramValue.Literal(value):null,features:Features);
    }
}
